// Helper to look up an article by id
function getArticleById(id) {
  return ArticlesData.find(a => a.id === id) || ArticlesData[0];
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { ArticlesData, getArticleById };
}
